const P = DATA.players, H = DATA.hist, LG = DATA.lega, QUOTE = DATA.quote;
const RN = {P:'Portieri', D:'Difensori', C:'Centrocampisti', A:'Attaccanti'};
const ORD = ['P','D','C','A'];
const byId = Object.fromEntries(P.map(p=>[p.id,p]));
const $ = s => document.querySelector(s);
const n2 = v => v===null||v===undefined ? '–' : (+v).toFixed(2);
const n1 = v => v===null||v===undefined ? '–' : (+v).toFixed(1);

// stato: cosa ho preso io, cosa hanno preso gli altri, quale riga è aperta.
// veri: prezzi realmente pagati osservati durante questa asta (i miei acquisti,
// o quelli letti con la fotocamera) — servono a ricalibrare il costo atteso
// di chi resta, non solo a segnare chi è assegnato.
let S = {mie:{}, altrui:{}, veri:{}, open:null, ruolo:'ALL', q:'', taken:false,
         sq:'ALL', vd:'ALL', tit:'ALL', ord:'mkt', bud:false};
const st = S; st.rip = 'lega'; st.usaGer = true;


/* ---------- importazione dati ----------
   Tre fonti aggiornabili senza rigenerare il file: il listone (chi c'è e quanto
   è quotato), i prezzi medi realmente pagati, le gerarchie alla prima giornata.
   Il riconoscimento è per nome normalizzato, la stessa chiave del database. */

function chiave(nome){
  return String(nome||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase().replace(/['`]/g,'').replace(/[.\-]/g,' ')
    .replace(/\s+/g,' ').trim();
}
function spezza(riga, sep){
  // la colonna RM del listone contiene punti e virgola ("Dd;Ds;E"): senza
  // rispettare le virgolette la riga si spacca e le colonne slittano
  const out = []; let cella = '', dentro = false;
  for(let i=0;i<riga.length;i++){
    const c = riga[i];
    if(c === '"'){
      if(dentro && riga[i+1] === '"'){ cella += '"'; i++; }
      else dentro = !dentro;
    } else if(c === sep && !dentro){ out.push(cella); cella = ''; }
    else cella += c;
  }
  out.push(cella);
  return out.map(x=>x.trim());
}
function tabella(testo){
  const righe = testo.trim().split(/\r?\n/).filter(r=>r.trim());
  if(!righe.length) return [];
  const t = righe[0];
  const sep = t.includes('\t') ? '\t'
            : (t.split(';').length > t.split(',').length ? ';' : ',');
  return righe.map(r=>spezza(r, sep));
}
function intestazione(righe){
  for(let i=0;i<Math.min(righe.length,10);i++)
    if(righe[i].some(c=>/^nome$/i.test(c.trim()))) return i;
  return -1;
}
function indice(hdr, test){
  for(let i=0;i<hdr.length;i++) if(test(hdr[i].toLowerCase().trim())) return i;
  return -1;
}
function numero(v){
  const n = parseFloat(String(v).replace(',', '.').replace(/[^0-9.\-]/g,''));
  return isFinite(n) ? n : null;
}
function leggi(testo){
  const righe = tabella(testo);
  const h = intestazione(righe);
  if(h < 0) throw new Error('non trovo la colonna "Nome" nell\'intestazione');
  return {hdr: righe[h], corpo: righe.slice(h+1).filter(r=>r.length>1 && r.some(c=>c))};
}

const IMPORT = {
  quot(testo){
    const {hdr, corpo} = leggi(testo);
    const iN = indice(hdr, c=>c==='nome');
    const iR = indice(hdr, c=>c==='r'||c==='ruolo');
    const iS = indice(hdr, c=>c.startsWith('squadra'));
    const iQ = indice(hdr, c=>c.includes('qt.a')||c==='qta'||c==='qt'||c.includes('quotazione'));
    const iF = indice(hdr, c=>c==='fvm'||(c.includes('fvm')&&!c.includes('1000')));
    if(iF<0 && iQ<0) throw new Error('serve almeno una colonna FVM o Qt.A');
    const vecchi = Object.assign({}, byId);
    const nuovi = [], visti = new Set();
    for(const r of corpo){
      const nome = r[iN]; if(!nome) continue;
      const id = chiave(nome); if(!id || visti.has(id)) continue;
      visti.add(id);
      const v = vecchi[id];
      const base = v ? Object.assign({}, v) : {
        id, n: nome, sq: '?', r: 'C', rm: '', fvm: 1, qt: 1, ptot: null,
        fma: null, mva: null, pva: null, pt: null, tr: null,
        aff: 'nessuno storico', omo: false, pct: null, tit: null, st: null, mod: null,
        s3: null, pv3: null, mv3: null, fm3: null, gf3: null, ass3: null,
        amm3: null, gs3: null, sc: null, pvt: null, fmc: null, fmb: null,
        gft: null, ast: null, pfm: null, ppv: null, pmv: null };
      base.n = nome;
      if(iR>=0 && ORD.includes((r[iR]||'').toUpperCase())) base.r = r[iR].toUpperCase();
      if(iS>=0 && r[iS]) base.sq = r[iS];
      if(iQ>=0 && numero(r[iQ])!=null) base.qt = numero(r[iQ]);
      base.fvm = (iF>=0 && numero(r[iF])!=null) ? numero(r[iF])
               : (iQ>=0 && numero(r[iQ])!=null ? numero(r[iQ])*3 : base.fvm);
      nuovi.push(base);
    }
    if(nuovi.length < 20) throw new Error('ho letto solo '+nuovi.length+' righe, controlla il formato');
    const conStorico = nuovi.filter(x=>x.ptot!==null).length;
    P.length = 0; nuovi.forEach(x=>P.push(x));
    Object.keys(byId).forEach(k=>delete byId[k]);
    P.forEach(x=>byId[x.id]=x);
    for(const k of Object.keys(S.mie)) if(!byId[k]) delete S.mie[k];
    for(const k of Object.keys(S.altrui)) if(!byId[k]) delete S.altrui[k];
    return P.length+' giocatori, '+conStorico+' con storico, '+(P.length-conStorico)+' nuovi';
  },
  p1000(testo){
    const {hdr, corpo} = leggi(testo);
    const iN = indice(hdr, c=>c==='nome');
    let iP = indice(hdr, c=>c.includes('1000'));
    if(iP<0) iP = indice(hdr, c=>c.includes('media')||c.includes('prezzo'));
    if(iP<0) throw new Error('non trovo la colonna del prezzo su 1000');
    let n=0, ignorati=0;
    P.forEach(x=>{ x.p1000 = null; });
    for(const r of corpo){
      const p = byId[chiave(r[iN])], v = numero(r[iP]);
      if(!p){ if(r[iN]) ignorati++; continue; }
      if(v!=null && v>0){ p.p1000 = v; n++; }
    }
    return n+' prezzi applicati'+(ignorati?', '+ignorati+' nomi non nel listone':'');
  },
  ger(testo){
    const {hdr, corpo} = leggi(testo);
    const iN = indice(hdr, c=>c==='nome');
    const iP = indice(hdr, c=>c.includes('%')||c.includes('titolar')||c.includes('probab'));
    if(iP<0) throw new Error('non trovo la colonna della percentuale');
    const iS = indice(hdr, c=>c.includes('stato')||c.includes('nota'));
    let n=0;
    for(const r of corpo){
      const p = byId[chiave(r[iN])], v = numero(r[iP]);
      if(!p || v==null) continue;
      p.pct = Math.round(v<=1 ? v*100 : v);
      p.tit = p.pct >= 65;
      if(iS>=0) p.st = r[iS] || null;
      n++;
    }
    return n+' gerarchie aggiornate';
  }
};

