/* ---------- motore prezzi ----------
   Dentro ogni ruolo le proporzioni vengono dai prezzi medi reali, se importati,
   altrimenti dalla curva calibrata su di essi. Il monte crediti del ruolo viene
   dalla ripartizione scelta. Poi il prezzo consigliato corregge il mercato con
   il rendimento atteso, entro ±50%. */

/* La percentuale di titolarità alla prima è l'unico dato che sa cosa è successo
   in ritiro. Corregge i punti attesi: 90% lascia tutto com'è, 50% toglie un
   quinto, 10% dimezza. È un dato di UNA giornata: per questo si può spegnere e
   per questo non scende mai sotto la metà. */
function fattoreGerarchia(p){
  if(!st.usaGer || p.pct==null) return 1;
  return Math.min(1.05, Math.max(0.5, 0.5 + 0.5*(p.pct/90)));
}

$('#nsq').innerHTML = [6,8,10,12,14,16,18,20]
  .map(n=>'<option value="'+n+'"'+(n===LG.squadre?' selected':'')+'>'+n+' squadre</option>').join('');

function calcolaPrezzi(){
  const quote = st.rip==='media' ? DATA.quote_media : DATA.quote;
  P.forEach(p=>{ p.mkt = 1; p.fatt = 1; });
  for(const r of ORD){
    const pool = P.filter(x=>x.r===r);
    pool.forEach(x=>{ x.grezzo = x.p1000 > 0 ? x.p1000
      : DATA.curva[r].a * Math.pow(Math.max(x.fvm||0,1), DATA.curva[r].b); });
    const n = Math.min(LG.squadre*LG.slot[r], pool.length);
    const dentro = pool.slice().sort((a,b)=>b.grezzo-a.grezzo).slice(0,n);
    const somma = dentro.reduce((a,x)=>a+x.grezzo,0);
    const monte = quote[r]/100 * LG.budget * LG.squadre;
    dentro.forEach(x=>{ x.mkt = Math.max(1, Math.round(x.grezzo/somma*monte)); });

    pool.forEach(x=>{ x.pt2 = x.ptot===null||x.ptot===undefined ? null : x.ptot*fattoreGerarchia(x); });
    const d = dentro.filter(x=>x.mkt>1 && x.pt2!==null);
    if(d.length>=10){
      const xs=d.map(x=>Math.log(x.mkt)), ys=d.map(x=>x.pt2);
      const mx=xs.reduce((a,b)=>a+b,0)/xs.length, my=ys.reduce((a,b)=>a+b,0)/ys.length;
      let num=0, den=0;
      for(let i=0;i<xs.length;i++){ num+=(xs[i]-mx)*(ys[i]-my); den+=(xs[i]-mx)**2; }
      const b1 = den? num/den : 0, b0 = my - b1*mx;
      pool.forEach(x=>{
        if(x.mkt<=1 || x.pt2===null){ x.fatt=1; x.attesoPrezzo=null; return; }
        const atteso = Math.max(1, b0 + b1*Math.log(x.mkt));
        x.attesoPrezzo = Math.round(atteso);
        x.fatt = Math.min(1.5, Math.max(0.5, x.pt2/atteso));
      });
    }
  }
  P.forEach(p=>{
    p.val = Math.max(1, Math.round(p.mkt*p.fatt));
    p.min = Math.max(1, Math.round(p.val*0.85));
    p.max = Math.max(1, Math.round(p.val*1.15));
    p.marg = p.val - p.mkt;
    p.vd = p.mkt<=1 ? 'riempitivo'
         : p.fatt>=1.12 ? 'spingi'
         : p.fatt<=0.89 ? 'lascia' : 'prezzo giusto';
  });
  ricalibraConAsta();
}

/* ---------- ricalibrazione dal vivo ----------
   La curva sopra è calcolata a tavolino, prima che l'asta cominci. Ma un'asta
   ha un suo clima, e cambia in corsa: se i primi giocatori volano sopra il
   consigliato, probabilmente anche i prossimi costeranno più del previsto, e
   viceversa se vanno sotto. Confronto ogni prezzo realmente pagato (i miei
   acquisti, o quelli letti con la fotocamera) con quello che l'app aveva
   consigliato PRIMA di saperlo: lo scarto medio diventa un correttivo.
   Ogni ruolo usa il correttivo calcolato sulle SUE aggiudicazioni, appena ne
   ha almeno una; finché un ruolo non ha ancora venduto nessuno, prende il
   correttivo generale calcolato su tutte le aggiudicazioni viste finora (di
   qualsiasi ruolo) — così basta leggere UN solo giocatore, in un'asta appena
   iniziata, perché il costo atteso di TUTTI i giocatori residui si avvicini
   a come sta andando davvero l'asta, e non solo quello del suo ruolo. */
function reali(){
  const out = Object.assign({}, S.veri);
  for(const id in S.mie) if(out[id]==null) out[id] = S.mie[id];
  return out;
}
function ricalibraConAsta(){
  const r = reali();
  const media = arr => arr.reduce((a,b)=>a+b,0)/arr.length;
  const perRuolo = {}; ORD.forEach(ru=>perRuolo[ru]=[]);
  const tutti = [];
  for(const id in r){
    const p = byId[id];
    if(!p || p.mkt<=1) continue;
    const rap = r[id] / p.val;
    tutti.push(rap);
    if(perRuolo[p.r]) perRuolo[p.r].push(rap);
  }
  if(!tutti.length) return;
  const mGlobale = Math.min(1.5, Math.max(0.5, media(tutti)));
  for(const ru of ORD){
    const campione = perRuolo[ru];
    const daRuolo = campione.length>0;
    const m = Math.min(1.5, Math.max(0.5, daRuolo ? media(campione) : mGlobale));
    if(Math.abs(m-1) < 0.02) continue;
    P.forEach(x=>{
      if(x.r!==ru || x.mkt<=1 || r[x.id]!=null) return;
      x.val = Math.max(1, Math.round(x.val * m));
      x.min = Math.max(1, Math.round(x.val*0.85));
      x.max = Math.max(1, Math.round(x.val*1.15));
      x.marg = x.val - x.mkt;
      const rap = x.val / x.mkt;
      x.vd = rap>=1.12 ? 'spingi' : rap<=0.89 ? 'lascia' : 'prezzo giusto';
      x.astaCorr = m;
      x.astaCorrFonte = daRuolo ? 'ruolo' : 'globale';
    });
  }
}
$('#nsq').addEventListener('change', e=>{ LG.squadre=+e.target.value; calcolaPrezzi(); redraw(); });
$('#rip').addEventListener('change', e=>{ st.rip=e.target.value; calcolaPrezzi(); redraw(); });
