/* ---------- budget per ruolo ---------- */
// l'obiettivo di spesa per ruolo viene dalle aste vere della lega
function target(){
  const q = st.rip==='media' ? DATA.quote_media : QUOTE;
  return Object.fromEntries(ORD.map(r=>[r, Math.round(q[r]/100*LG.budget)]));
}

/* ---------- ripartizione dinamica ----------
   Il budget di ruolo non è una cifra fissa decisa all'inizio: è la fetta di
   quello che ti resta ADESSO. Se sfondi su un portiere, i crediti che mancano
   non spariscono nel nulla, vengono tolti agli altri reparti in proporzione.
   Ogni slot ancora vuoto si porta via almeno 1 credito: quello si mette da
   parte prima di spartire il resto. */
function ripartisci(c){
  const q = st.rip==='media' ? DATA.quote_media : QUOTE;
  const liberi = c.tot.liberi, resid = c.tot.resid;

  // niente slot da riempire, o budget già sfondato: non c'è niente da spartire
  if(liberi <= 0 || resid <= 0){ ORD.forEach(r=>c[r].quota = 0); return; }

  if(resid <= liberi){
    // non basta nemmeno un credito per slot: si spartisce alla pari quel che c'è
    let dato = 0;
    ORD.forEach((r,i)=>{
      c[r].quota = i===ORD.length-1 ? Math.max(0,resid-dato)
                 : Math.round(resid * (c[r].liberi/liberi));
      dato += c[r].quota;
    });
    return;
  }

  // il minimo garantito, poi il resto secondo il peso del ruolo
  const daSpartire = resid - liberi;
  const peso = r => c[r].slot ? q[r]/100 * (c[r].liberi/c[r].slot) : 0;
  const somma = ORD.reduce((a,r)=>a+peso(r), 0);
  let dato = 0;
  const attivi = ORD.filter(r=>c[r].liberi>0);
  attivi.forEach((r,i)=>{
    const base = c[r].liberi;
    c[r].quota = i===attivi.length-1
      ? resid - dato
      : base + Math.round(somma ? daSpartire*peso(r)/somma : daSpartire/attivi.length);
    dato += c[r].quota;
  });
  ORD.filter(r=>c[r].liberi<=0).forEach(r=>c[r].quota = 0);
}

function conti(){
  const c = {tot:{speso:0, n:0}};
  const T = target();
  ORD.forEach(r=>c[r]={speso:0, n:0, iniziale:T[r], slot:LG.slot[r]});
  for(const [id,pr] of Object.entries(S.mie)){
    const p = byId[id]; if(!p) continue;
    c[p.r].speso += pr; c[p.r].n++; c.tot.speso += pr; c.tot.n++;
  }
  c.tot.slot = ORD.reduce((a,r)=>a+LG.slot[r],0);
  c.tot.resid = LG.budget - c.tot.speso;
  c.tot.liberi = c.tot.slot - c.tot.n;
  ORD.forEach(r=>{ c[r].liberi = c[r].slot - c[r].n; });
  ripartisci(c);
  ORD.forEach(r=>{ c[r].resid = c[r].quota; c[r].target = c[r].speso + c[r].quota; });
  return c;
}

// quanto posso spendere ORA su un giocatore di quel ruolo, senza restare a secco
function cap(r, c){
  if(c[r].liberi <= 0) return 0;                                     // ruolo già pieno
  const globale = c.tot.resid - Math.max(0, c.tot.liberi - 1);       // 1 credito per ogni altro slot
  const ruolo   = c[r].quota  - Math.max(0, c[r].liberi - 1);        // dentro la fetta del ruolo
  return Math.max(0, Math.min(globale, Math.max(1, ruolo)));
}

/* ---------- testata ---------- */
function drawTop(){
  const c = conti();
  $('#cred').textContent = c.tot.resid;
  $('#credtot').textContent = ` / ${LG.budget}`;
  $('#slots').textContent = c.tot.liberi;
  const capAll = Math.max(...ORD.filter(r=>c[r].liberi>0).map(r=>cap(r,c)), 0);
  $('#capmax').textContent = c.tot.liberi ? capAll : '–';

  /* la barra dei crediti: quanto hai speso sul totale, e dove sta il muro
     dei crediti che non puoi toccare perché ti servono a riempire gli slot */
  const spesoPct = Math.min(100, c.tot.speso / LG.budget * 100);
  const minimoPct = Math.min(100, (LG.budget - c.tot.liberi) / LG.budget * 100);
  const f = $('#tbarfill');
  f.style.width = spesoPct + '%';
  f.classList.toggle('over', c.tot.speso > LG.budget - c.tot.liberi);
  $('#tbarmin').style.left = minimoPct + '%';
  const libero = c.tot.resid - c.tot.liberi;
  const corto = tipoSchermo() === 'telefono';
  const destra = !c.tot.liberi ? 'rosa completa'
    : libero < 0 ? `mancano ${-libero} cr per chiudere`
    : corto ? `<b>${libero}</b> spendibili`
    : `<b>${libero}</b> davvero spendibili, ${c.tot.liberi} da tenere per gli slot vuoti`;
  $('#tnote').innerHTML =
    `<span><b>${c.tot.speso}</b> spesi su ${LG.budget}${corto ? '' : ` · ${c.tot.n} giocatori`}</span>` +
    `<span class="${libero<0?'alert':''}">${destra}</span>`;

  /* Sul telefono i quattro blocchi a 88px non possono contenere una frase:
     restano la lettera, gli slot e i crediti che avanzano. Il resto sta nella rosa. */
  const stretto = tipoSchermo() === 'telefono';
  $('#roles').innerHTML = ORD.map(r=>{
    const x = c[r];
    const tot = x.speso + x.quota;
    const pct = tot ? Math.min(100, x.speso / tot * 100) : 0;
    const sforato = x.speso > x.iniziale;
    const val = x.liberi ? x.quota : '–';
    return `<div class="rb" style="--rc:var(--${r})">
      <div class="rt"><b>${r}</b><span>${x.n}/${x.slot}</span>${stretto?`<em>${val}</em>`:''}</div>
      <div class="rv">${val}<i> ${x.liberi
        ? 'da spendere · ' + x.speso + ' spesi' : 'completo · ' + x.speso + ' spesi'}</i></div>
      <div class="bar"><i class="${sforato?'over':''}" style="width:${pct}%"></i></div>
    </div>`;
  }).join('');
}

/* ---------- lista ---------- */
/* Laurientè, Konè, Soulè, Dodò: in asta nessuno si ferma a mettere l'accento.
   Confronto le forme senza segni diacritici. */
const senzaAccenti = t => t.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
P.forEach(p=>{ p._cerca = senzaAccenti(p.n + ' ' + p.sq); });

function filtra(){
  const q = senzaAccenti(S.q), c = conti();
  const out = P.filter(p=>{
    if(S.ruolo!=='ALL' && p.r!==S.ruolo) return false;
    if(!S.taken && (S.mie[p.id]!==undefined || S.altrui[p.id])) return false;
    if(S.sq!=='ALL' && p.sq!==S.sq) return false;
    if(S.vd!=='ALL' && p.vd!==S.vd) return false;
    if(S.tit==='tit' && !p.tit) return false;
    if(S.tit==='pan' && (p.tit || p.pct==null)) return false;
    if(S.tit==='ok' && p.st) return false;
    if(S.bud && p.min > cap(p.r, c)) return false;
    if(q && !p._cerca.includes(q)) return false;
    return true;
  });
  const k = S.ord;
  out.sort((a,b)=>{
    if(k==='n') return a.n.localeCompare(b.n);
    if(k==='conv') return (b.fatt||0)-(a.fatt||0) || b.mkt-a.mkt;
    const va = a[k]==null ? -1 : a[k], vb = b[k]==null ? -1 : b[k];
    return vb-va || a.n.localeCompare(b.n);
  });
  return out;
}

/* ---------- filtri attivi ----------
   Ogni filtro acceso diventa una targhetta che si può togliere:
   così non resti a chiederti perché un giocatore non compare. */
const ETICHETTE = {
  ruolo:{nome:'Ruolo', val:v=>({P:'Portieri',D:'Difensori',C:'Centrocampisti',A:'Attaccanti'}[v]||v)},
  sq:   {nome:'Squadra', val:v=>v},
  vd:   {nome:'Consiglio', val:v=>v},
  tit:  {nome:'Prima giornata',
         val:v=>({tit:'solo titolari',pan:'solo panchina',ok:'senza problemi'}[v]||v)},
  bud:  {nome:'Budget', val:()=>'solo alla mia portata'},
  q:    {nome:'Cerca', val:v=>'"'+v+'"'},
  taken:{nome:'Assegnati', val:()=>'inclusi'}
};
const SPENTO = {ruolo:'ALL', sq:'ALL', vd:'ALL', tit:'ALL', bud:false, q:'', taken:false};

function drawChips(nRis){
  const attivi = Object.keys(SPENTO).filter(k=> S[k] !== SPENTO[k]);
  let html = `<span class="count"><b>${nRis}</b> giocatori</span>`;
  html += attivi.map(k=>`<span class="chip"><u>${ETICHETTE[k].nome}</u>${ETICHETTE[k].val(S[k])}
    <button data-off="${k}" aria-label="Togli il filtro ${ETICHETTE[k].nome}">×</button></span>`).join('');
  if(attivi.length>1) html += `<button class="chipall" id="azzeraFiltri">Togli tutti i filtri</button>`;
  $('#chips').innerHTML = html;
}

function spegniFiltro(k){
  S[k] = SPENTO[k];
  if(k==='q') $('#q').value='';
  if(k==='ruolo') [...$('#seg').children].forEach(x=>x.setAttribute('aria-pressed', x.dataset.r==='ALL'));
  if(k==='sq') $('#fsq').value='ALL';
  if(k==='vd') $('#fvd').value='ALL';
  if(k==='tit') $('#ftit').value='ALL';
  if(k==='bud') $('#fbud').checked=false;
  if(k==='taken') $('#showtaken').checked=false;
  S.open=null; segnaSelect(); drawList();
}

