/* i menù che filtrano qualcosa si accendono d'oro */
function segnaSelect(){
  $('#fsq').classList.toggle('on', S.sq!=='ALL');
  $('#fvd').classList.toggle('on', S.vd!=='ALL');
  $('#ftit').classList.toggle('on', S.tit!=='ALL');
  $('#ford').classList.toggle('on', S.ord!=='mkt');
}

function drawList(){
  const c = conti(), rows = filtra();
  drawChips(rows.length);
  if(!rows.length){
    $('#list').innerHTML = `<div class="none"><b>Nessuno risponde a questi filtri</b>
      <span>Allarga la ricerca o togli qualche filtro per rivedere la lista.</span>
      <button id="azzeraFiltri2">Togli tutti i filtri</button></div>`;
    return;
  }
  $('#list').innerHTML = rows.map(p=>{
    const mio = S.mie[p.id]!==undefined, altro = !!S.altrui[p.id];
    const cp = cap(p.r, c);
    const tetto = Math.min(p.max, cp);
    let nota = p.mkt<=1 ? 'fuori mercato' : `mercato ${p.mkt}`, cls = '';
    if(mio) nota = 'preso da te';
    else if(altro) nota = 'preso da altri';
    else if(cp===0){ nota = c[p.r].liberi<=0 ? 'ruolo pieno' : 'crediti finiti'; cls='stop'; }
    else if(cp < p.mkt){ nota = `budget: max ${cp}`; cls='cap'; }
    else if(cp < p.max){ nota = `arrivi a ${cp}`; cls='cap'; }
    const mg = p.vd==='spingi' ? 'up' : p.vd==='lascia' ? 'dn'
             : p.vd==='riempitivo' ? '' : 'eq';
    const gl = p.vd==='spingi' ? '▲' : p.vd==='lascia' ? '▼' : p.vd==='riempitivo' ? '·' : '=';
    const vdTxt = p.vd==='prezzo giusto' ? 'giusto' : p.vd==='riempitivo' ? 'riemp.' : p.vd;
    const rng = p.mkt<=1 ? '<b class="dim">1</b>' : `<b><span class="lo">${p.min}</span>–${p.max}</b>`;
    const flag = p.aff!=='ok' ? ` <span class="flag">⚑</span>` : '';
    return `<div class="crd ${S.open===p.id?'aperta':''} ${mio||altro?'presa':''}"
      style="--rc:var(--${p.r})">
      <div class="row ${mio||altro?'taken':''} ${S.open===p.id?'open':''}" data-id="${p.id}">
        <span class="rl" style="background:var(--${p.r})">${p.r}</span>
        <span class="who"><b>${p.n}${flag}</b><span>${p.sq} · Fm ${n2(p.fma)} · ${n1(p.pva)} pres.</span></span>
        <span class="rng">${mio
          ? `<b style="color:var(--gold)">${S.mie[p.id]}</b>`
          : `<b><span class="lo">${p.min}</span>–${tetto}</b>`}<small class="${cls}">${nota}</small></span>
        <span class="sotto">
          <span class="ger ${p.st?'ko':p.tit?'t':''}" title="${p.st||(p.tit?'titolare':'panchina')}"
          >${p.pct==null?'':`<b>${p.pct}%</b>${p.st?p.st.slice(0,3):p.tit?'tit':'pan'}`}</span>
          <span class="extra">Qt ${p.qt} · FVM ${p.fvm}<i>${n2(p.fma)} Fm</i></span>
          <span class="vd ${mg}" title="${p.vd}"><i>${gl}</i><span class="txt">${vdTxt}</span></span>
        </span>
      </div>
      ${S.open===p.id ? actionBar(p, c) : ''}
    </div>`;
  }).join('');
}

function actionBar(p, c){
  const mio = S.mie[p.id]!==undefined, altro = !!S.altrui[p.id];
  if(mio || altro) return `<div class="act">
    <span class="lbl">${mio?`nella tua rosa a ${S.mie[p.id]} crediti`:'assegnato a un altro'}</span>
    <button class="del" data-free="${p.id}">Libera</button>
    <button data-info="${p.id}">Statistiche</button></div>`;
  const cp = cap(p.r, c), sugg = Math.min(p.mkt, cp||1);
  return `<div class="act">
    ${termometro(p, cp, sugg)}
    <span class="lbl">Pagato</span>
    <input type="number" inputmode="numeric" id="pr" value="${sugg}" min="1" max="${c.tot.resid}">
    <button class="ok" data-buy="${p.id}">Preso io</button>
    <button class="oth" data-other="${p.id}">Ad altri</button>
    <button data-info="${p.id}">Statistiche</button>
    <span class="hint">${p.mkt<=1
      ? 'Fuori dai posti che la lega assorbirà: riempitivo da prendere a 1.'
      : `Costerà circa <b>${p.mkt}</b>, ne vale <b>${p.val}</b>. Range ${p.min}–${p.max}.`}
      ${cp<p.max?`Il tuo budget di ruolo ti ferma a ${cp}.`:''}
      ${p.vd==='spingi'?'Rende più di quanto rendono i giocatori a quel prezzo: rilancia fino al tetto.'
        :p.vd==='lascia'?'Rende meno di quanto rendono i giocatori a quel prezzo: lascialo agli altri.'
        :p.vd==='riempitivo'?'':'Prezzo allineato al rendimento: prendilo solo se ti serve il ruolo.'}
      ${p.pct!=null?` Alla prima è dato ${p.pct}% ${p.tit?'titolare':'in panchina'}${p.st?', '+p.st:''}.`:''}
      ${p.astaCorr?` <b>Corretto dai prezzi reali di questa asta</b>: ${p.astaCorrFonte==='ruolo'?'i '+RN[p.r].toLowerCase()+' stanno costando':'l\'asta nel complesso sta andando'} ${p.astaCorr>1?'più del previsto':'meno del previsto'} (${p.astaCorr>1?'+':''}${Math.round((p.astaCorr-1)*100)}%).`:''}</span>
  </div>`;
}

/* ---------- termometro d'asta ----------
   In asta la domanda non è "quanto vale" ma "posso ancora alzare".
   La barra mostra le quattro zone in cui può cadere l'offerta e dove sei adesso. */
function termometro(p, cp, val){
  if(p.mkt<=1) return '';
  const fondo = Math.max(p.max, cp, val) * 1.12;
  const pos = v => Math.max(0, Math.min(100, v/fondo*100));
  const finMin = pos(p.min), finMax = pos(p.max), finCap = pos(cp);
  const oltre = Math.min(finMax, finCap), tetto = Math.max(finMax, finCap);
  return `<div class="trk">
    <div class="trkbar" id="trkbar">
      <div class="z sotto"  style="left:0;width:${finMin}%"></div>
      <div class="z giusto" style="left:${finMin}%;width:${Math.max(0,oltre-finMin)}%"></div>
      <div class="z sopra"  style="left:${oltre}%;width:${Math.max(0,tetto-oltre)}%"></div>
      <div class="z fuori"  style="left:${finCap}%;right:0"></div>
      <span class="tick" style="left:${pos(p.mkt)}%"></span>
      <span class="now" id="trknow" style="left:${pos(val)}%"></span>
    </div>
    <div class="trklab">
      <span style="left:${finMin}%">${p.min}</span>
      <span class="g" style="left:${pos(p.mkt)}%">mercato ${p.mkt}</span>
      <span style="left:${finMax}%">${p.max}</span>
      ${cp < p.max*1.3 ? `<span class="r" style="left:${finCap}%">tetto ${cp}</span>` : ''}
    </div>
    <div class="trkmsg" id="trkmsg"></div>
  </div>`;
}

function aggiornaTermometro(){
  const bar = $('#trkbar'); if(!bar) return;
  const p = byId[S.open], c = conti(), cp = cap(p.r, c);
  const val = Math.max(0, +($('#pr')||{}).value || 0);
  const fondo = Math.max(p.max, cp, val) * 1.12;
  const now = $('#trknow');
  now.style.left = Math.max(0, Math.min(100, val/fondo*100)) + '%';
  now.classList.toggle('over', val > cp);
  let m;
  if(val > cp)         m = `<b>${val}</b> sfonda il tetto di ${cp}: non ti resterebbe da coprire gli altri slot.`;
  else if(val > p.max) m = `<b>${val}</b> è sopra il massimo consigliato di ${p.max}.`;
  else if(val >= p.min)m = `<b>${val}</b> è dentro il range consigliato.`;
  else                 m = `<b>${val}</b> è sotto il minimo: se lo prendi a questa cifra è un affare.`;
  $('#trkmsg').innerHTML = m;
}

