/* ---------- scheda statistiche (pressione prolungata) ---------- */
function scheda(id){
  const p = byId[id], h = H[id]||[];
  const kpi = (u,b,i)=>`<div class="kpi"><u>${u}</u><b>${b}</b>${i?`<i>${i}</i>`:''}</div>`;
  const pct = (u,v)=>`<div class="kpi"><u>${u}</u><b>${v===null?'–':Math.round(v)}<i>°</i></b>
    <div class="pctbar"><i style="width:${v||0}%"></i></div></div>`;
  const media = p.s3 ? `
    <div class="kpis">
      ${kpi('Presenze', n1(p.pv3), `su ${p.s3} stagioni`)}
      ${kpi('Media voto', n2(p.mv3))}
      ${kpi('Fantamedia', n2(p.fm3))}
      ${kpi(p.r==='P'?'Gol subiti':'Gol', n1(p.r==='P'?p.gs3:p.gf3))}
      ${kpi('Assist', n1(p.ass3))}
      ${kpi('Ammonizioni', n1(p.amm3))}
    </div>` : `<p class="sub">Nessuna presenza in Serie A nelle stagioni coperte dal database.</p>`;
  const carr = p.sc ? `<div class="kpis">
      ${kpi('Stagioni', p.sc)} ${kpi('Presenze totali', p.pvt)}
      ${kpi('Fm carriera', n2(p.fmc))} ${kpi('Miglior Fm', n2(p.fmb))}
      ${kpi('Gol totali', p.gft)} ${kpi('Assist totali', p.ast)}</div>` : '';
  const tab = h.length ? `<table>
    <thead><tr><th>Stagione</th><th>Squadra</th><th>Pv</th><th>Mv</th><th>Fm</th>
      <th>Gf</th><th>Ass</th><th>Gs</th><th>Amm</th><th>Esp</th></tr></thead>
    <tbody>${h.map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3].toFixed(2)}</td>
      <td>${x[4].toFixed(2)}</td><td>${x[5]}</td><td>${x[6]}</td><td>${x[7]}</td>
      <td>${x[8]}</td><td>${x[9]}</td></tr>`).join('')}</tbody></table>` : '';
  $('#card').innerHTML = `
    <h3>${p.n}</h3>
    <div class="sub">${p.sq} · ${RN[p.r]}${p.rm?' · Mantra '+p.rm:''} · listino ${p.qt} ·
      mercato ${p.mkt} · consigliato ${p.val} · range ${p.min}–${p.max} · ${p.vd}
      ${p.attesoPrezzo?`· a quel prezzo ci si aspettano ${p.attesoPrezzo} punti, lui ne rende ${p.ptot}`:''}</div>
    ${p.omo?`<p class="sub" style="color:var(--gold)">Cognome condiviso con un altro giocatore in stagioni
      passate: lo storico qui sotto potrebbe mescolare due persone.</p>`:''}
    ${p.aff!=='ok'?`<p class="sub" style="color:var(--gold)">Dato ${p.aff}: le medie sotto sono fragili.</p>`:''}
    ${p.pct!=null?`<div class="sub" style="margin-top:12px">Alla prima giornata (${DATA.gerarchie.aggiornamento})</div>
    <div class="kpis">
      ${kpi('Titolarità', p.pct+'%', p.tit?'in campo dal 1\u2032':'in panchina')}
      ${kpi('Modulo', p.mod||'–')}
      ${p.st?kpi('Stato', p.st):''}
    </div>`:''}
    <div class="sub" style="margin-top:12px">Medie ultime tre stagioni</div>
    ${media}
    <div class="sub">Attese 2026-27 e posizione nel ruolo</div>
    <div class="kpis">
      ${kpi('Fm attesa', n2(p.fma))} ${kpi('Mv attesa', n2(p.mva))} ${kpi('Presenze attese', n1(p.pva))}
      ${pct('Percentile Fm', p.pfm)} ${pct('Percentile presenze', p.ppv)} ${pct('Percentile Mv', p.pmv)}
    </div>
    ${carr?`<div class="sub">Carriera nel database</div>${carr}`:''}
    ${tab?`<div class="sub">Stagione per stagione</div>${tab}`:''}
    <button class="close" id="close">Chiudi</button>`;
  $('#sheet').classList.add('on');
}

/* ---------- pressione prolungata ---------- */
let lpTimer=null, lpFired=false, lpX=0, lpY=0;
function lpStart(e){
  const row = e.target.closest('.row'); if(!row) return;
  const t = e.touches ? e.touches[0] : e;
  lpX=t.clientX; lpY=t.clientY; lpFired=false;
  lpTimer = setTimeout(()=>{ lpFired=true; if(navigator.vibrate) navigator.vibrate(18);
    scheda(row.dataset.id); }, 450);
}
function lpMove(e){
  if(!lpTimer) return;
  const t = e.touches ? e.touches[0] : e;
  if(Math.abs(t.clientX-lpX)>12 || Math.abs(t.clientY-lpY)>12){ clearTimeout(lpTimer); lpTimer=null; }
}
function lpEnd(){ clearTimeout(lpTimer); lpTimer=null; }
const list = $('#list');
list.addEventListener('touchstart', lpStart, {passive:true});
list.addEventListener('touchmove', lpMove, {passive:true});
list.addEventListener('touchend', lpEnd);
list.addEventListener('mousedown', lpStart);
list.addEventListener('mousemove', lpMove);
list.addEventListener('mouseup', lpEnd);
list.addEventListener('mouseleave', lpEnd);
list.addEventListener('contextmenu', e=>{ const r=e.target.closest('.row');
  if(r){ e.preventDefault(); scheda(r.dataset.id); } });

/* ---------- click ---------- */
list.addEventListener('click', e=>{
  if(lpFired){ lpFired=false; return; }
  const b = e.target.closest('button');
  if(b){
    if(b.dataset.info){ scheda(b.dataset.info); return; }
    if(b.dataset.buy){
      const v = Math.max(1, parseInt($('#pr').value)||1);
      delete S.altrui[b.dataset.buy]; S.mie[b.dataset.buy] = v; S.open=null; redraw(); return;
    }
    if(b.dataset.other){ delete S.mie[b.dataset.other]; S.altrui[b.dataset.other]=1; S.open=null; redraw(); return; }
    if(b.dataset.free){ delete S.mie[b.dataset.free]; delete S.altrui[b.dataset.free]; S.open=null; redraw(); return; }
  }
  const row = e.target.closest('.row'); if(!row) return;
  S.open = S.open===row.dataset.id ? null : row.dataset.id;
  drawList();
  const inp = $('#pr'); if(inp){ inp.focus(); inp.select(); }
});

