/* se si passa al formato PC la rosa torna nella colonna: il velo va tolto */
let ultimoTipo = tipoSchermo();
function tipoSchermo(){
  const w = window.innerWidth;
  return w < 600 ? 'telefono' : w < 1024 ? 'tablet' : 'pc';
}
function adatta(){
  const t = tipoSchermo();
  document.documentElement.dataset.dev = t;
  if(t !== ultimoTipo){
    ultimoTipo = t;
    if(t === 'pc') rosaApri(false);
    if(t !== 'telefono') $('#opz').classList.remove('on');
    $('#top').classList.toggle('chiusa', t === 'telefono');
    $('#apriTop').setAttribute('aria-expanded', t !== 'telefono');
    redraw();
  }
}
let tmr; window.addEventListener('resize', ()=>{ clearTimeout(tmr); tmr = setTimeout(adatta, 150); });
window.addEventListener('orientationchange', ()=> setTimeout(adatta, 250));
adatta();

/* ---------- lettura prezzi dalla fotocamera ----------
   Durante l'asta si inquadra la schermata con gli ultimi aggiudicati: l'OCR
   legge il testo, ogni riga che finisce con un numero plausibile diventa un
   candidato "nome + prezzo", il nome viene abbinato al listone (stessa
   normalizzazione usata per il database, con un margine per gli errori di
   lettura). Prima di toccare qualsiasi cosa l'utente vede e può correggere
   ogni riga: un OCR sbagliato non deve rovinare i conti dell'asta. */

// il motore OCR pesa alcuni MB: si scarica solo al primo utilizzo, non al
// caricamento della pagina
let tesseractCarico = null;
function caricaTesseract(){
  if(window.Tesseract) return Promise.resolve();
  if(tesseractCarico) return tesseractCarico;
  tesseractCarico = new Promise((ris, err)=>{
    const s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';
    s.onload = ris;
    s.onerror = () => err(new Error('motore OCR non scaricabile: controlla la connessione'));
    document.head.appendChild(s);
  });
  return tesseractCarico;
}

// distanza di Levenshtein: quanti caratteri separano due parole. Serve per
// riconoscere un nome anche quando l'OCR sbaglia una o due lettere.
function distanza(a, b){
  const m=a.length, n=b.length;
  if(!m) return n; if(!n) return m;
  let prec = Array.from({length:n+1}, (_,i)=>i);
  for(let i=1;i<=m;i++){
    const cur=[i];
    for(let j=1;j<=n;j++) cur[j] = a[i-1]===b[j-1] ? prec[j-1] : 1+Math.min(prec[j-1],prec[j],cur[j-1]);
    prec = cur;
  }
  return prec[n];
}
function trovaGiocatore(testo){
  const id = chiave(testo);
  if(!id) return null;
  if(byId[id]) return byId[id];
  if(id.length<3) return null;
  let migliore=null, meglioD=Infinity;
  for(const p of P){
    const soglia = Math.max(1, Math.floor(p.id.length*0.3));
    const d = distanza(id, p.id);
    if(d<=soglia && d<meglioD){ meglioD=d; migliore=p; }
  }
  return migliore;
}
// da un blocco di testo OCR alle righe "nome + prezzo": ogni riga che finisce
// con un numero credibile (1..budget) è un candidato
function leggiRigheAsta(testo){
  const righe = String(testo||'').split(/\r?\n/).map(r=>r.trim()).filter(Boolean);
  const out = [], visti = new Set();
  for(const riga of righe){
    const m = riga.match(/(\d{1,3})\s*(?:cr\.?|crediti)?\s*$/i);
    if(!m) continue;
    if(m.index>0 && /\d/.test(riga[m.index-1])) continue; // numero troppo lungo (es. "9999"): non è un prezzo credibile
    const prezzo = parseInt(m[1],10);
    if(!prezzo || prezzo<1 || prezzo>LG.budget) continue;
    const nomeTxt = riga.slice(0, m.index).replace(/[^A-Za-zÀ-ÿ'.\- ]/g,' ').replace(/\s+/g,' ').trim();
    if(nomeTxt.length<2) continue;
    const p = trovaGiocatore(nomeTxt);
    const id = p ? p.id : chiave(nomeTxt)+':'+out.length; // chiave unica anche senza match
    if(visti.has(id)) continue;
    visti.add(id);
    out.push({nomeTxt, nome: p?p.n:nomeTxt, id: p?p.id:null, prezzo});
  }
  return out;
}

let ocrBozza = [];
function popolaDatalist(){
  $('#dlGiocatori').innerHTML = P.map(p=>`<option value="${p.n}">`).join('');
}
function chiudiOcr(){ $('#ocrSheet').classList.remove('on'); }
function resetOcrUI(){
  ocrBozza = [];
  $('#ocrFile').value = '';
  $('#ocrPreviewWrap').style.display = 'none';
  $('#ocrStato').textContent = '';
  $('#ocrRisultati').innerHTML = '';
  $('#ocrApplica').style.display = 'none';
}
$('#fabocr').addEventListener('click', ()=>{
  popolaDatalist(); resetOcrUI();
  $('#ocrSheet').classList.add('on');
});

function drawOcrRisultati(){
  const box = $('#ocrRisultati');
  if(!ocrBozza.length){
    box.innerHTML = '<p class="sub">Nessuna riga con nome e prezzo trovata: prova una foto più vicina e a fuoco, con meno riflessi.</p>';
    return;
  }
  box.innerHTML = ocrBozza.map((r,i)=>`
    <div class="ocrriga" data-i="${i}">
      <input class="ocrnome ${r.id?'':'ko'}" list="dlGiocatori" value="${r.nome.replace(/"/g,'&quot;')}"
        placeholder="nome giocatore">
      <input class="ocrprezzo" type="number" min="1" max="${LG.budget}" value="${r.prezzo}">
      <select class="ocrdest"><option value="altri">Un avversario</option><option value="io">Io</option></select>
      <label class="chk"><input type="checkbox" class="ocrok" ${r.id?'checked':''}> usa</label>
    </div>`).join('');
}

$('#ocrFile').addEventListener('change', async e=>{
  const f = e.target.files[0]; if(!f) return;
  ocrBozza = [];
  $('#ocrRisultati').innerHTML = '';
  $('#ocrApplica').style.display = 'none';
  const url = URL.createObjectURL(f);
  $('#ocrPreview').src = url;
  $('#ocrPreviewWrap').style.display = 'block';
  $('#ocrStato').textContent = 'Carico il motore OCR…';
  try{
    await caricaTesseract();
    $('#ocrStato').textContent = 'Sto leggendo la foto… 0%';
    const {data} = await Tesseract.recognize(f, 'ita', {
      logger: m => { if(m.status==='recognizing text')
        $('#ocrStato').textContent = `Sto leggendo la foto… ${Math.round((m.progress||0)*100)}%`; }
    });
    ocrBozza = leggiRigheAsta(data.text);
    $('#ocrStato').textContent = ocrBozza.length
      ? `${ocrBozza.length} rig${ocrBozza.length===1?'a':'he'} con un prezzo trovat${ocrBozza.length===1?'a':'e'}: controllale prima di applicare.`
      : 'Non ho trovato righe con nome e prezzo. Prova con una foto più nitida o più vicina.';
    drawOcrRisultati();
    if(ocrBozza.length) $('#ocrApplica').style.display = 'block';
  }catch(err){
    $('#ocrStato').textContent = 'Errore nella lettura: ' + err.message;
  }finally{
    URL.revokeObjectURL(url);
  }
});

function ocrApplica(){
  const righe = [...$('#ocrRisultati').querySelectorAll('.ocrriga')];
  let n=0, saltati=0;
  righe.forEach(riga=>{
    if(!riga.querySelector('.ocrok').checked) return;
    const nomeVal = riga.querySelector('.ocrnome').value;
    const prezzo = Math.max(1, parseInt(riga.querySelector('.ocrprezzo').value,10)||0);
    const dest = riga.querySelector('.ocrdest').value;
    const p = trovaGiocatore(nomeVal);
    if(!p || !prezzo){ saltati++; return; }
    if(dest==='io'){ delete S.altrui[p.id]; S.mie[p.id]=prezzo; }
    else{ delete S.mie[p.id]; if(S.altrui[p.id]===undefined) S.altrui[p.id]=1; }
    S.veri[p.id]=prezzo; n++;
  });
  if(!n){ alert('Nessuna riga applicata: seleziona almeno un giocatore riconosciuto con "usa".'); return; }
  calcolaPrezzi(); redraw(); chiudiOcr();
  alert(`${n} prezzi registrati e usati per ricalibrare il costo atteso di chi resta.`
    + (saltati?` (${saltati} righe saltate: nome non riconosciuto)`:''));
}
$('#ocrApplica').addEventListener('click', ocrApplica);

/* ---------- salva / carica ---------- */
document.addEventListener('click', e=>{
  if(e.target.id!=='save') return;
  const importati = P.filter(x=>x.p1000>0).map(x=>[x.id, x.p1000]);
  const blob = new Blob([JSON.stringify({mie:S.mie, altrui:S.altrui, veri:S.veri, p1000:importati,
    rip:st.rip, squadre:LG.squadre, ts:Date.now()})],
    {type:'application/json'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'asta_2026_27_stato.json'; a.click();
  URL.revokeObjectURL(a.href);
});
document.addEventListener('change', e=>{
  if(e.target.id!=='load' || !e.target.files.length) return;
  const fr = new FileReader();
  fr.onload = () => { try{ const o=JSON.parse(fr.result);
    S.mie=o.mie||{}; S.altrui=o.altrui||{}; S.veri=o.veri||{}; S.open=null;
    if(o.rip) st.rip=o.rip;
    if(o.squadre) LG.squadre=o.squadre;
    if(o.p1000){ P.forEach(x=>x.p1000=null);
      o.p1000.forEach(([k,v])=>{ if(byId[k]) byId[k].p1000=v; }); }
    calcolaPrezzi(); redraw();
  }catch(_){ alert('File non leggibile.'); } };
  fr.readAsText(e.target.files[0]);
});

function redraw(){
  drawTop(); drawList(); drawRose();
  const c = conti();
  $('#fab').textContent = `Rosa ${c.tot.n}/${c.tot.slot}`;
}
calcolaPrezzi(); redraw();


/* ---------- RIVALI 2.0 / V67.1 ----------
   Modulo isolato: non modifica il motore prezzi. Ogni profilo è sempre
   inizializzato con P/D/C/A, evitando l'errore "undefined.p" della V67. */
const RIVAL_COUNT = 7;
const RIVAL_NAMES = Array.from({length:RIVAL_COUNT}, (_,i)=>`Rivale ${i+1}`);
const RIVAL_NEED = {P:3,D:8,C:8,A:6};
const RIVAL_REQUIRED = {P:1,D:4,C:3,A:3};

function nuovoProfiloRivale(i){
  return {
    id:i, nome:RIVAL_NAMES[i], budget:1000,
    slot:{P:3,D:8,C:8,A:6},
    presi:{P:0,D:0,C:0,A:0},
    speso:0, acquisti:[],
    aggressivita:{P:0,D:0,C:0,A:0},
    overpay:{P:0,D:0,C:0,A:0},
  };
}
function inizializzaRivali(){
  if(!Array.isArray(window._rivaliV671) || window._rivaliV671.length!==RIVAL_COUNT){
    window._rivaliV671 = Array.from({length:RIVAL_COUNT}, (_,i)=>nuovoProfiloRivale(i));
  }
  window._rivaliV671.forEach((r,i)=>{
    if(!r || typeof r!=='object') window._rivaliV671[i]=nuovoProfiloRivale(i);
    const x=window._rivaliV671[i];
    x.slot=x.slot||{}; x.presi=x.presi||{}; x.acquisti=Array.isArray(x.acquisti)?x.acquisti:[];
    ORD.forEach(role=>{ if(typeof x.slot[role]!=='number') x.slot[role]=RIVAL_NEED[role]; if(typeof x.presi[role]!=='number') x.presi[role]=0; if(typeof x.aggressivita?.[role]!=='number') x.aggressivita[role]=0; if(typeof x.overpay?.[role]!=='number') x.overpay[role]=0; });
    if(typeof x.budget!=='number') x.budget=1000;
    if(typeof x.speso!=='number') x.speso=0;
  });
  return window._rivaliV671;
}

function rivaliStato(){
  const rs=inizializzaRivali();
  // Compatibilità con S.altrui: se non esiste un assegnatario, NON inventiamo
  // quale rivale abbia comprato il giocatore. Gli acquisti generici restano
  // semplicemente mercato osservato.
  return rs;
}

function rivalePrezzoMassimo(r,p){
  if(!r || !p) return 0;
  const role=p.r;
  const slots=r.slot[role] ?? RIVAL_NEED[role];
  if(slots<=0 || r.budget<=0) return 0;
  // Riserva minima per gli slot futuri: ogni slot non può costare meno di 1.
  const reserve=Math.max(0, slots-1);
  const cap=Math.max(1, r.budget-reserve);
  return Math.min(cap, Number(p.max)||Number(p.mkt)||1);
}

function rivaleInteresse(r,p){
  if(!r || !p || !p.r) return {score:0,offer:0,reason:'nessuna capacità'};
  const role=p.r, slots=r.slot[role] ?? RIVAL_NEED[role];
  if(slots<=0 || r.budget<=0) return {score:0,offer:0,reason:'ruolo completo'};
  const base=Math.max(1,Number(p.mkt)||Number(p.val)||1);
  const max=rivalePrezzoMassimo(r,p);
  if(max<=0) return {score:0,offer:0,reason:'budget insufficiente'};
  const affordability=Math.min(1,max/base);
  const quality=Math.max(0,Math.min(1,(Number(p.val)||Number(p.mkt)||1)/Math.max(1,base)));
  const scarcity=slots<=2 ? .12 : slots<=4 ? .07 : 0;
  const starter=(r.acquisti.length===0 && p.mkt>20) ? .04 : 0;
  const score=Math.round(Math.max(0,Math.min(100, affordability*62 + quality*22 + scarcity*100 + starter*100)));
  let reason=slots<=2?'necessità ruolo alta':'slot ruolo disponibili';
  if(max < base*.8) reason='può interessarsi ma non sostenere il prezzo';
  else if(max >= base*1.05) reason='ha margine per competere';
  return {score, offer:Math.max(1,Math.min(max,Math.round(base*(0.88+Math.min(0.2,score/500))))),reason};
}

function previsioneGiocatoreRivali(p){
  const rs=rivaliStato();
  return rs.map(r=>({...rivaleInteresse(r,p), rival:r})).sort((a,b)=>b.score-a.score);
}

function renderRivali(){
  const rs=rivaliStato();
  const all=P.filter(p=>S.mie[p.id]===undefined && !S.altrui[p.id]);
  const focus=all.sort((a,b)=>(Number(b.mkt)||0)-(Number(a.mkt)||0)).slice(0,14);
  const target=focus[0];
  const summary=target ? previsioneGiocatoreRivali(target).filter(x=>x.score>=35).length : 0;
  $('#rivaliSummary').innerHTML=`<b>${RIVAL_COUNT} profili inizializzati</b> · ${summary} rivali con capacità concreta sul miglior obiettivo attuale. <span>Gli acquisti segnati genericamente “ad altri” non vengono attribuiti arbitrariamente a un rivale.</span>`;
  $('#rivaliGrid').innerHTML=rs.map(r=>{
    const poss=focus.map(p=>({p,...rivaleInteresse(r,p)})).filter(x=>x.score>=35).sort((a,b)=>b.score-a.score).slice(0,3);
    const best=poss[0];
    return `<article class="riv-cardrow"><div class="riv-title"><b>${r.nome}</b><span>${r.budget} cr · ${Object.values(r.presi).reduce((a,b)=>a+b,0)} acquistati</span></div><div class="riv-profile"><span>P ${r.slot.P}</span><span>D ${r.slot.D}</span><span>C ${r.slot.C}</span><span>A ${r.slot.A}</span></div>${best?`<div class="riv-target"><strong>${best.p.n}</strong><span>${best.score}% interesse · ~${best.offer} cr</span><small>${best.reason}</small></div>`:`<div class="riv-target muted">Nessun obiettivo concreto tra i primi disponibili.</div>`}</article>`;
  }).join('');
}

function apriRivali(){
  inizializzaRivali();
  renderRivali();
  $('#rivaliSheet').classList.add('on');
  $('#rivaliSheet').setAttribute('aria-hidden','false');
}
function chiudiRivali(){ $('#rivaliSheet').classList.remove('on'); $('#rivaliSheet').setAttribute('aria-hidden','true'); }

function aggiornaRivaliDaAssegnazione(){
  // Punto di integrazione volutamente conservativo: senza sapere quale dei 7
  // avversari ha effettuato l'acquisto non assegniamo dati inventati.
  inizializzaRivali();
}

document.addEventListener('click',e=>{
  if(e.target.closest('#rivaliBtn')) apriRivali();
  if(e.target.closest('#rivaliClose') || e.target.id==='rivaliSheet') chiudiRivali();
});

// Hook sicuro: il pannello può essere aperto anche appena caricata la pagina.
try { inizializzaRivali(); } catch(e) { console.warn('Rivali init:',e); }
